/* Exact legacy ripple deformation on a persistent GPU mesh. */
static const char *gridVertexSource="#version 120\nuniform sampler2D uGeometry;\nuniform vec4 uView[3],uRipple[100],uInverse[100],uWaterUV,uVision;\nuniform vec2 uProj;\nuniform float uNear,uPhase;\nuniform int uRippleCount;\nvarying vec2 vUV;\nvarying vec3 vWorld;\nvarying vec4 vColor;\nfloat fixedSin(float p){return texture2D(uGeometry,vec2((mod(p,4096.0)+.5)/4096.0,.25)).r;}\n// Base-256 decomposition keeps integer products exact in IEEE single precision.\nfloat fixedMul(float a,float b){\n float h=floor(b/256.0),l=b-h*256.0,t=a*h;\n return floor(t/256.0)+floor((mod(t,256.0)*256.0+a*l)/65536.0);\n}\nvoid main(){\n vec3 w=gl_MultiTexCoord1.xyz;\n vec2 p=sign(w.xz)*floor(abs(w.xz)+.5);\n float offset=floor(fixedSin(p.x+p.y+uPhase)/2048.0)+floor(fixedSin(p.x-p.y*2.0+floor(uPhase*.5))/4096.0);\n for(int i=0;i<100;i++){\n  if(i>=uRippleCount)break;\n  vec2 d=abs(p-uRipple[i].xy);\n  float a=max(d.x,d.y)+floor(min(d.x,d.y)*.5);\n  if(a<uRipple[i].z)offset+=fixedMul(uRipple[i].w,fixedSin(fixedMul(a,uInverse[i].x)));\n }\n offset=min(clamp(offset,-256.0,256.0),gl_Vertex.x);\n w.y+=offset;vWorld=w;\n vec2 warp=texture2D(uGeometry,vec2((offset+256.5)/4096.0,.75)).rg;\n vUV=((w.xz-uWaterUV.xy)*.25+warp)*uWaterUV.zw+vec2(1.0/256.0);\n vColor=vec4(uVision.rgb,(128.0-offset*.25)/255.0);\n vec3 q=vec3(dot(uView[0],vec4(w,1.0)),dot(uView[1],vec4(w,1.0)),dot(uView[2],vec4(w,1.0)));\n gl_Position=vec4(q.x*uProj.x,-q.y*uProj.y,q.z-2.0*uNear,q.z);\n}\n";
